declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';$postId=(int)($_GET['post_id']??0);v17_content('post',$postId,current_user());if($postId<1)json_response(['comments'=>[]]);try{$st=db()->prepare('SELECT c.id,c.parent_comment_id,c.body,c.created_at,u.id user_id,u.username,u.display_name,u.avatar_url FROM feed_post_comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=? ORDER BY c.id ASC LIMIT 150');$st->execute([$postId]);$rows=$st->fetchAll();json_response(['comments'=>array_map(static fn($r)=>['id'=>(int)$r['id'],'parentCommentId'=>$r['parent_comment_id']?(int)$r['parent_comment_id']:null,'body'=>(string)$r['body'],'createdAt'=>(string)$r['created_at'],'user'=>['id'=>(int)$r['user_id'],'username'=>(string)$r['username'],'displayName'=>(string)$r['display_name'],'avatarUrl'=>$r['avatar_url']?:null]],$rows)]);}catch(Throwable $e){json_response(['message'=>'Yorumlar alınamadı.'],500);}
